using System;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Collections.Generic;
using System.Linq;
using System.IO;

namespace SecureCertLib
{
    public enum ValidationResult { Valid, Invalid, Revoked, Expired, UntrustedRoot }

    public class AuditEntry
    {
        public DateTime Timestamp { get; set; }
        public string Subject { get; set; }
        public string Issuer { get; set; }
        public ValidationResult Result { get; set; }
        public string Details { get; set; }
    }

    public class CertificateAuditLogger
    {
        private readonly List<AuditEntry> _entries = new List<AuditEntry>();
        private readonly object _lock = new object();

        public void LogValidation(X509Certificate2 cert, ValidationResult result, string details)
        {
            lock (_lock)
            {
                _entries.Add(new AuditEntry
                {
                    Timestamp = DateTime.UtcNow,
                    Subject = cert.Subject,
                    Issuer = cert.Issuer,
                    Result = result,
                    Details = details
                });
            }
        }

        public IReadOnlyList<AuditEntry> GetEntries() => _entries.AsReadOnly();
    }

    public class ChainPolicyConfig
    {
        public bool RequireRevocationCheck { get; set; } = true;
        public bool AllowUnknownCA { get; set; } = false;
        public int MaxChainDepth { get; set; } = 5;
        public TimeSpan ClockSkewTolerance { get; set; } = TimeSpan.FromMinutes(5);
    }

    public class CertificateValidator
    {
        private readonly CertificateAuditLogger _logger;
        private readonly ChainPolicyConfig _config;
        private readonly X509Certificate2Collection _trustedRoots;

        public CertificateValidator(CertificateAuditLogger logger, ChainPolicyConfig config,
            X509Certificate2Collection trustedRoots)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _config = config ?? throw new ArgumentNullException(nameof(config));
            _trustedRoots = trustedRoots ?? throw new ArgumentNullException(nameof(trustedRoots));
        }

        public ValidationResult ValidateCertificate(X509Certificate2 certificate)
        {
            if (certificate == null)
                throw new ArgumentNullException(nameof(certificate));

            var result = PerformChainValidation(certificate);
            _logger.LogValidation(certificate, result, BuildDetailString(certificate, result));
            return result;
        }

        private ValidationResult PerformChainValidation(X509Certificate2 cert)
        {
            // Step 1: Check temporal validity with clock skew tolerance
            var temporalResult = CheckTemporalValidity(cert);
            if (temporalResult != ValidationResult.Valid)
                return temporalResult;

            // Step 2: Build and verify the chain
            using (var chain = new X509Chain())
            {
                ConfigureChainPolicy(chain);
                chain.ChainPolicy.ExtraStore.AddRange(_trustedRoots);

                bool chainBuilt = chain.Build(cert);
                var chainResult = EvaluateChainStatus(chain, chainBuilt);
                return chainResult;
            }
        }

        private ValidationResult CheckTemporalValidity(X509Certificate2 cert)
        {
            var now = DateTime.UtcNow;
            var effectiveNotBefore = cert.NotBefore.ToUniversalTime() - _config.ClockSkewTolerance;
            var effectiveNotAfter = cert.NotAfter.ToUniversalTime() + _config.ClockSkewTolerance;

            if (now < effectiveNotBefore || now > effectiveNotAfter)
                return ValidationResult.Expired;

            return ValidationResult.Valid;
        }

        private void ConfigureChainPolicy(X509Chain chain)
        {
            chain.ChainPolicy.RevocationMode = _config.RequireRevocationCheck
                ? X509RevocationMode.Online
                : X509RevocationMode.NoCheck;

            chain.ChainPolicy.VerificationFlags = X509VerificationFlags.NoFlag;

            if (_config.AllowUnknownCA)
            {
                chain.ChainPolicy.VerificationFlags |= X509VerificationFlags.AllowUnknownCertificateAuthority;
            }
        }

        private ValidationResult EvaluateChainStatus(X509Chain chain, bool chainBuilt)
        {
            if (chainBuilt && chain.ChainStatus.Length == 0)
                return ValidationResult.Valid;

            // Even if Build() returned true, check individual status flags
            var statusFlags = chain.ChainStatus
                .Select(s => s.Status)
                .Aggregate(X509ChainStatusFlags.NoError, (acc, flag) => acc | flag);

            return MapStatusToResult(statusFlags, chain);
        }

        private ValidationResult MapStatusToResult(X509ChainStatusFlags flags, X509Chain chain)
        {
            // Check revocation first (highest priority)
            if (flags.HasFlag(X509ChainStatusFlags.Revoked))
                return ValidationResult.Revoked;

            // Check expiration
            if (flags.HasFlag(X509ChainStatusFlags.NotTimeValid) ||
                flags.HasFlag(X509ChainStatusFlags.NotTimeNested))
                return ValidationResult.Expired;

            // Check trust anchor
            if (flags.HasFlag(X509ChainStatusFlags.UntrustedRoot) ||
                flags.HasFlag(X509ChainStatusFlags.PartialChain))
            {
                return HandleUntrustedRoot(chain);
            }

            // Any remaining error flags mean invalid
            if (flags != X509ChainStatusFlags.NoError)
                return ValidationResult.Invalid;

            return ValidationResult.Valid;
        }

        private ValidationResult HandleUntrustedRoot(X509Chain chain)
        {
            // If AllowUnknownCA is set, we still verify the root is in our trusted store
            // by comparing thumbprints
            if (!_config.AllowUnknownCA)
                return ValidationResult.UntrustedRoot;

            var chainRoot = chain.ChainElements[chain.ChainElements.Count - 1].Certificate;
            return VerifyAgainstTrustedStore(chainRoot);
        }

        private ValidationResult VerifyAgainstTrustedStore(X509Certificate2 rootCert)
        {
            // Compare using cryptographic thumbprint for strong identity verification
            var rootThumbprint = rootCert.Thumbprint;
            if (rootThumbprint == null)
                return ValidationResult.UntrustedRoot;

            foreach (var trusted in _trustedRoots)
            {
                if (rootThumbprint.Equals(trusted.Thumbprint, StringComparison.OrdinalIgnoreCase))
                    return ValidationResult.Valid;
            }

            return ValidationResult.UntrustedRoot;
        }

        private string BuildDetailString(X509Certificate2 cert, ValidationResult result)
        {
            return $"Subject={cert.Subject}; Thumbprint={cert.Thumbprint}; " +
                   $"SerialNumber={cert.SerialNumber}; Result={result}; " +
                   $"ValidFrom={cert.NotBefore:O}; ValidTo={cert.NotAfter:O}";
        }
    }
}
